// German C3 (C2 mastery) practice rooms: 6 modules x 12 rooms x 3 questions.
window.deRooms = window.deRooms || {};
deRooms.C3 = [
  // Module 1: Near-native Tone & Flexibility
  [
    {t:"Fillers and reactions",s:"Vocabulary",qs:[
      {q:"'Das ist mir Wurst.' means:",opts:["I couldn't care less.","I'm really hungry.","That's my favourite.","I don't understand it."],a:0,ex:"Colloquial 'Wurst' here means 'all the same', so the idiom signals indifference, not food."},
      {q:"Which word describes a casual, slightly careless style?",opts:["salopp","gediegen","förmlich","gehoben"],a:0,ex:"'salopp' = casual or sloppy; 'gediegen' is refined, 'förmlich' formal and 'gehoben' elevated."},
      {q:"'Mensch, bist du groß geworden!' – here 'Mensch!' expresses:",opts:["surprise","an insult","a request","a doubt"],a:0,ex:"As an interjection 'Mensch!' works like 'Gosh!' or 'Wow!'; it does not address a person."}]},
    {t:"Particles: eh, ohnehin, sowieso",s:"Vocabulary",qs:[
      {q:"'Ich wollte ohnehin gehen.' – 'ohnehin' means:",opts:["anyway","hardly","again","early"],a:0,ex:"'ohnehin' (like 'sowieso') signals that the action would have happened regardless."},
      {q:"Which word is the most colloquial equivalent of 'ohnehin'?",opts:["eh","zwar","etwa","bloß"],a:0,ex:"Spoken 'eh' means 'anyway' as in 'Das klappt eh nicht'; zwar, etwa and bloß have other functions."},
      {q:"Which word is the opposite of 'salopp' in register?",opts:["gediegen","lässig","locker","flapsig"],a:0,ex:"'gediegen' means refined and of solid quality; lässig, locker and flapsig are all casual."}]},
    {t:"Rhythm and particle stress",s:"Pronunciation",qs:[
      {q:"In 'Genau das meine ich.', which word carries the contrastive accent?",opts:["das","genau","meine","ich"],a:0,say:"Genau das meine ich.",ex:"The demonstrative 'das' in the Vorfeld bears the contrast: exactly THAT, not something else."},
      {q:"Where is the stress in 'sowieso'?",opts:["so-wie-SO","SO-wie-so","so-WIE-so","equal stress"],a:0,say:"sowieso",ex:"'sowieso' is stressed on its final syllable [zo-vi-ZO], unlike most native German words."},
      {q:"Modal particles like 'ja', 'doch' and 'eh' are normally:",opts:["unstressed","strongly stressed","always sentence-final","spoken with rising pitch"],a:0,say:"Das weißt du ja.",ex:"Particles are unstressed; a stressed 'JA' or 'DOCH' becomes emphasis or contradiction instead."}]},
    {t:"The Vorfeld for emphasis",s:"Grammar",qs:[
      {q:"Which sentence puts 'diesen Punkt' in focus?",opts:["Diesen Punkt finde ich entscheidend.","Ich finde diesen Punkt entscheidend.","Ich finde entscheidend diesen Punkt.","Finde ich diesen Punkt entscheidend."],a:0,ex:"Moving the object into position 1 (Vorfeld) marks it as topic and emphasis; the verb stays second."},
      {q:"In 'Gestern habe ich ihn getroffen.', what fills the Vorfeld?",opts:["Gestern","habe","ich","ihn"],a:0,ex:"The Vorfeld is everything before the finite verb; here the time adverb pushes the subject behind it."},
      {q:"Complete: '___ geht es mir gar nicht.' (That's not my point at all.)",opts:["Darum","Davon","Dafür","Damit"],a:0,ex:"'es geht um etwas' takes 'um', so the pronominal adverb is 'darum'; in first position it is stressed."}]},
    {t:"Particles and word order",s:"Grammar",qs:[
      {q:"Which sentence places 'ohnehin' correctly?",opts:["Das wollte ich ohnehin sagen.","Das ohnehin wollte ich sagen.","Ohnehin das wollte ich sagen.","Das wollte ich sagen ohnehin."],a:0,ex:"Particles sit in the middle field after the finite verb, never after the final infinitive."},
      {q:"Which sentence shows a typical learner mistake?",opts:["Heute ich gehe ins Kino.","Heute gehe ich ins Kino.","Ins Kino gehe ich heute.","Ich gehe heute ins Kino."],a:0,ex:"Only one constituent may precede the finite verb; after 'Heute' the subject must follow the verb."},
      {q:"Which order of pronouns is standard?",opts:["Ich habe es ihm gestern gesagt.","Ich habe ihm es gestern gesagt.","Ich habe gestern es ihm gesagt.","Ich habe gestern ihm es gesagt."],a:0,ex:"Unstressed pronouns cluster right after the finite verb, with accusative 'es' before the dative."}]},
    {t:"Reading: reading the tone",s:"Reading",qs:[
      {q:"Read: 'Na ja, das Konzert war eh ausverkauft, also ist es mir Wurst, dass ich krank war.' How does the writer feel?",opts:["indifferent","furious","very sad","excited"],a:0,ex:"'eh' (anyway) and 'mir Wurst' show the writer lost nothing by being ill and doesn't mind."},
      {q:"Read: 'Sehr geehrte Frau Dr. Lenz, gestatten Sie mir eine Anmerkung.' The register is:",opts:["formal","salopp","ironic","dialectal"],a:0,ex:"'Sehr geehrte', the title and 'gestatten Sie mir' are markers of a formal written register."},
      {q:"Read: 'Toll, schon wieder Stau. Genau das habe ich heute gebraucht.' The writer is being:",opts:["ironic","sincere","grateful","neutral"],a:0,ex:"Praising something annoying ('Toll', 'genau das gebraucht') signals verbal irony: the opposite is meant."}]},
    {t:"Listening: tone and intent",s:"Listening",qs:[
      {q:"Listen. What is the speaker's attitude?",say:"Na ja, so richtig überzeugt bin ich nicht.",opts:["hesitant doubt","full agreement","open anger","pure joy"],a:0,ex:"'Na ja' softens what follows, and 'nicht so richtig überzeugt' signals polite doubt."},
      {q:"Listen. What happened to the speaker?",say:"Mensch, ich hab mich total verhaspelt!",opts:["They got tongue-tied.","They got lost.","They lost their keys.","They overslept."],a:0,ex:"'sich verhaspeln' means to stumble over one's words; 'Mensch' adds frustration."},
      {q:"Listen. What does the speaker mean?",say:"Das hätten Sie mir ruhig früher sagen können.",opts:["They are mildly reproachful.","They are thanking you warmly.","They are asking for advice.","They are apologising."],a:0,ex:"'ruhig' with Konjunktiv II 'hätten … können' politely criticises that something was not done."}]},
    {t:"Switching registers",s:"Speaking",qs:[
      {q:"At a family dinner your phone rings: it's an important client. Best opening?",opts:["Guten Abend, Herr Weber, schön, dass Sie anrufen.","Na, was gibt's denn, alter Schwede? Erzähl mal!","Moment, ich hab grad echt keinen Bock drauf.","Hallo, wer stört denn da beim Essen?"],a:0,ex:"With a client you switch instantly to formal 'Sie', title and name; the others are family-table slang."},
      {q:"A friend tells you their trip was cancelled. Most natural reaction?",opts:["Mensch, so ein Pech!","Ich bedauere dies sehr.","Das ist mir Wurst.","Gestatten Sie eine Frage?"],a:0,ex:"'Mensch, so ein Pech!' is warm and colloquial; the formal phrase sounds cold and 'mir Wurst' is rude."},
      {q:"In a meeting you want to soften disagreement. Which is best?",opts:["Na ja, ganz so einfach ist es vielleicht nicht.","Das ist doch totaler Quatsch, was Sie da sagen.","Da liegen Sie aber völlig falsch, Herr Kollege.","Ist mir doch egal, machen Sie, was Sie wollen."],a:0,ex:"'Na ja' plus 'vielleicht' and 'ganz so … nicht' hedge the objection without attacking the speaker."}]},
    {t:"One invitation, three tones",s:"Writing",qs:[
      {q:"Which invitation fits a letter to the mayor?",opts:["Wir würden uns freuen, Sie bei unserem Empfang begrüßen zu dürfen.","Komm doch einfach vorbei, das wird bestimmt total lustig!","Hey, hast du Bock auf 'ne kleine Feier am Samstag?","Kommen Sie halt mal vorbei, wenn Sie gerade Zeit haben."],a:0,ex:"Konjunktiv II 'würden uns freuen' with 'begrüßen zu dürfen' is the ceremonial formula; 'halt mal' is casual."},
      {q:"Choose the correctly written sentence.",opts:["Das ist mir sowieso egal.","Das ist mir so wie so egal.","Das ist mir sowie so egal.","Das ist mir so wieso egal."],a:0,ex:"'sowieso' is written as one word; 'sowie' on its own is a conjunction meaning 'as well as'."},
      {q:"Fill the gap: 'Sehr geehrte Damen und Herren, wir laden ___ herzlich zu unserem Empfang ein.'",opts:["Sie","euch","dich","ihnen"],a:0,ex:"'Sehr geehrte Damen und Herren' requires formal 'Sie', capitalised, in the accusative after 'einladen'."}]},
    {t:"Register and politeness",s:"Culture",qs:[
      {q:"Using 'du' with a new senior colleague before it is offered is usually seen as:",opts:["too familiar","very polite","standard practice","old-fashioned"],a:0,ex:"In many German workplaces the senior person offers 'du'; assuming it can seem presumptuous."},
      {q:"'Das ist mir Wurst' in a formal board meeting would sound:",opts:["inappropriately casual","perfectly neutral","elegantly ironic","formal and dated"],a:0,ex:"It is a colloquial idiom; in formal settings 'Das ist für mich nicht entscheidend' fits better."},
      {q:"In a German meeting, 'Das finde ich nicht gut.' about a proposal is generally:",opts:["acceptable and factual","a serious insult","meant as a joke","extremely rude"],a:0,ex:"German professional culture values directness (Sachlichkeit): criticising an idea is not personal."}]},
    {t:"Tone recap",s:"Review",qs:[
      {q:"'gediegen' best describes:",opts:["a refined, high-quality interior","a cheap, badly furnished flat","a loud, crowded student bar","a sudden, rather angry reply"],a:0,ex:"'gediegen' means solid, tasteful and of good quality, often with a slightly conservative touch."},
      {q:"In 'Das wollte ich ohnehin sagen.', 'ohnehin' can be replaced by:",opts:["sowieso","trotzdem","dennoch","jedoch"],a:0,ex:"'sowieso' and 'ohnehin' both mean 'anyway'; trotzdem and dennoch mean 'nevertheless'."},
      {q:"Which reflexive verb means 'to get tongue-tied'?",opts:["sich verhaspeln","sich verlaufen","sich verfahren","sich verrechnen"],a:0,ex:"'sich verhaspeln' = to stumble over words; verlaufen/verfahren = get lost, verrechnen = miscalculate."}]},
    {t:"Tone masterclass",s:"Challenge",qs:[
      {q:"'Ruf doch mal an!' – what does 'doch mal' add?",opts:["a friendly, encouraging tone","a sharp, angry tone","a sense of past time","a formal distance"],a:0,ex:"'doch mal' softens the imperative into a casual, friendly suggestion rather than an order."},
      {q:"Which request is pragmatically the most distant toward the listener?",opts:["Ich darf Sie bitten, den Raum zu verlassen.","Geh doch bitte mal kurz raus, ja?","Kannst du vielleicht kurz rausgehen?","Wärst du so lieb und gehst kurz raus?"],a:0,ex:"'Ich darf Sie bitten' is a cool, formal formula that disguises a firm command as politeness."},
      {q:"Which is NOT a well-formed German sentence?",opts:["Entscheidend diesen Punkt finde ich.","Diesen Punkt finde ich entscheidend.","Entscheidend finde ich diesen Punkt.","Ich finde diesen Punkt entscheidend."],a:0,ex:"Only one constituent may fill the Vorfeld; 'Entscheidend' and 'diesen Punkt' together break verb-second."}]}
  ],
  // Module 2: Dialect Awareness
  [
    {t:"Regional greetings",s:"Vocabulary",qs:[
      {q:"'Moin' is a typical greeting in:",opts:["Northern Germany","Southern Bavaria","Eastern Austria","Western Switzerland"],a:0,ex:"'Moin' is used all day in the north, e.g. Hamburg or Bremen, not only in the morning."},
      {q:"Which greeting would you most likely hear in Zurich?",opts:["Grüezi","Moin","Servus","Tach"],a:0,ex:"'Grüezi' (from 'Gott grüez i') is the standard polite Swiss German greeting."},
      {q:"'Servus' can mean:",opts:["both hello and goodbye","only good night","thank you very much","excuse me, please"],a:0,ex:"In Bavaria and Austria 'Servus' (Latin 'your servant') is an informal greeting and farewell."}]},
    {t:"Rolls, months and parking",s:"Vocabulary",qs:[
      {q:"'die Semmel' is the southern word for:",opts:["bread roll","sausage","cake","pretzel"],a:0,ex:"Bavaria and Austria say 'Semmel', the north 'Brötchen', parts of the southwest 'Weck' or 'Weckle'."},
      {q:"In Austria, January is usually called:",opts:["Jänner","Jannuar","Jannes","Jänuar"],a:0,ex:"'Jänner' is the official Austrian standard form; 'Januar' is used in Germany and Switzerland."},
      {q:"The Swiss standard verb for 'to park' is:",opts:["parkieren","parkern","parkisieren","parkeln"],a:0,ex:"Swiss Standard German uses 'parkieren' where Germany has 'parken'; it is a Helvetism, not an error."}]},
    {t:"Sounds of the regions",s:"Pronunciation",qs:[
      {q:"In many Swiss dialects, the 'k' at the start of 'Kind' sounds like:",opts:["a throaty 'ch' sound","a soft 'g' sound","an English 'k'","a silent letter"],a:0,say:"Chind",ex:"Many Swiss dialects shift initial k to a fricative: 'Chind', 'Chuchi' for Kind, Küche."},
      {q:"Saxon (Sächsisch) speech is known for:",opts:["softening p, t, k toward b, d, g","rolling every r very strongly","dropping all final vowels","a nasal, French-like accent"],a:0,ex:"Saxon is famous for soft consonants, e.g. 'Gaffee' for Kaffee ('die weechen Gonsonanten')."},
      {q:"Listen. Low German keeps old consonants. What is the standard form?",say:"dat Water",opts:["das Wasser","der Wetter","die Watte","das Wetter"],a:0,ex:"Low German skipped the High German consonant shift: t stays t, so 'dat Water' = 'das Wasser'."}]},
    {t:"Regional grammar",s:"Grammar",qs:[
      {q:"In southern Germany and Austria, the perfect of 'sitzen' usually takes:",opts:["sein: Ich bin gesessen.","haben: Ich habe gesessen.","werden: Ich werde gesessen.","no auxiliary at all"],a:0,ex:"Southern and Austrian standard use 'sein' with sitzen, liegen and stehen; the north uses 'haben'."},
      {q:"Colloquial southern German: '___ Maria kommt später.'",opts:["Die","Der","Das","Den"],a:0,ex:"Southern colloquial speech puts an article before first names: 'die Maria', 'der Thomas'."},
      {q:"Why do Bavarian speakers rarely say 'ich ging'?",opts:["Southern speech uses the Perfekt","The verb is irregular there","The Präteritum sounds rude","They use the Futur instead"],a:0,ex:"In the south the simple past has largely vanished from speech; 'ich bin gegangen' is used instead."}]},
    {t:"Dialect forms decoded",s:"Grammar",qs:[
      {q:"Bavarian 'Mia san mia' corresponds to standard:",opts:["Wir sind wir.","Mir ist mir.","Mich sind mich.","Wir san wir."],a:0,ex:"Bavarian uses 'mia' for 'wir' and 'san' for 'sind'; the phrase is FC Bayern's motto."},
      {q:"Swabian diminutives typically end in:",opts:["-le","-chen","-erl","-li"],a:0,ex:"Swabian says 'Häusle'; Bavarian uses -erl, Swiss German -li and the standard language -chen."},
      {q:"'Gell?' at the end of a southern sentence means:",opts:["isn't it? / right?","good night to you","go away now","thank you kindly"],a:0,ex:"'gell' (or 'gelt') is a southern tag question, like standard 'nicht wahr?' or northern 'ne?'."}]},
    {t:"Reading: postcards",s:"Reading",qs:[
      {q:"Read: 'Servus aus Wien! Im Jänner ist es hier eiskalt, aber die Semmeln beim Bäcker sind ein Traum.' Which month is it?",opts:["January","June","July","December"],a:0,ex:"'Jänner' is the Austrian standard word for January, fitting the Vienna setting."},
      {q:"Read: 'Grüezi mitenand! Wir haben das Auto am Bahnhof parkiert und sind zu Fuss weiter.' Where is the writer?",opts:["Switzerland","Hamburg","Saxony","Vienna"],a:0,ex:"'Grüezi', 'parkiert' and 'Fuss' spelt without ß are all Swiss features."},
      {q:"Read: 'Moin! Wir sitzen in Kiel am Hafen und essen Fischbrötchen.' Which statement is true?",opts:["The writer is in the north.","The writer is in Bavaria.","It must be early morning.","The writer dislikes fish."],a:0,ex:"Kiel is on the Baltic coast, and 'Moin' is the northern greeting at any time of day."}]},
    {t:"Listening: where is it from?",s:"Listening",qs:[
      {q:"Listen. Where does the speaker most likely come from?",say:"Grüß Gott, ich hätte gern zwei Semmeln.",opts:["Bavaria or Austria","Hamburg or Bremen","Berlin or Potsdam","Kiel or Lübeck"],a:0,ex:"'Grüß Gott' and 'Semmeln' are both southern usage, typical of Bavaria and Austria."},
      {q:"Listen. Which region does this customer point to?",say:"Moin, ich hätte gern zwei Brötchen.",opts:["the north","the south","Switzerland","Austria"],a:0,ex:"'Moin' and 'Brötchen' are both typically northern German."},
      {q:"Listen. What does the speaker want to do?",say:"Grüezi, wo kann ich hier parkieren?",opts:["park the car","buy bread","find a hotel","catch a train"],a:0,ex:"'parkieren' is the Swiss form of 'parken'; 'Grüezi' confirms a Swiss speaker."}]},
    {t:"Greeting like a local",s:"Speaking",qs:[
      {q:"You enter a small bakery in Munich. Most fitting greeting?",opts:["Grüß Gott!","Moin moin!","Grüezi!","Tach auch!"],a:0,ex:"'Grüß Gott' is the polite everyday greeting in Bavaria; 'Grüezi' is Swiss and 'Moin' northern."},
      {q:"A Hamburg colleague says 'Moin!' at 4 pm. Best reply?",opts:["Moin!","Guten Morgen!","Gute Nacht!","Grüezi!"],a:0,ex:"'Moin' is not tied to the morning in the north, so you simply return it."},
      {q:"You can't follow a strong Swabian speaker. Most polite request?",opts:["Könnten Sie das bitte etwas langsamer sagen?","Reden Sie gefälligst endlich Hochdeutsch!","Was soll denn dieses Gebrabbel hier?","Ihr Dialekt ist mir einfach zu primitiv."],a:0,ex:"A neutral request to slow down is polite; demanding Hochdeutsch or mocking a dialect offends."}]},
    {t:"Writing about varieties",s:"Writing",qs:[
      {q:"Choose the correct Swiss Standard German spelling.",opts:["Die Strasse ist gross.","Die Straße ist gross.","Die Strasse ist groß.","Die Strahse ist gross."],a:0,ex:"Swiss Standard German never uses ß and writes 'ss' consistently: Strasse, gross."},
      {q:"Fill the gap: 'Hochdeutsch ist die ___, Dialekte sind regionale Varietäten.'",opts:["Standardsprache","Fachsprache","Fremdsprache","Mundart"],a:0,ex:"'Standardsprache' is the supra-regional norm; 'Mundart' is a synonym of 'Dialekt'."},
      {q:"Which sentence compares the varieties correctly?",opts:["In der Schweiz sagt man 'parkieren', in Deutschland 'parken'.","In der Schweiz sagt man 'parken', in Deutschland 'parkieren'.","In Österreich sagt man 'Januar', in Deutschland 'Jänner'.","In Hamburg sagt man 'Semmel', in München 'Brötchen'."],a:0,ex:"'parkieren' is Swiss; the other sentences swap the regions of Jänner and Semmel/Brötchen."}]},
    {t:"Dialect and identity",s:"Culture",qs:[
      {q:"Plattdeutsch (Low German) is traditionally spoken in:",opts:["Northern Germany","the Alpine regions","Switzerland","Saxony and Thuringia"],a:0,ex:"Low German belongs to the northern lowlands, from the coast to Westphalia and Brandenburg."},
      {q:"In Switzerland, Swiss German dialect is:",opts:["used by all classes in daily speech","only spoken by older farmers","forbidden in public offices","the language of all newspapers"],a:0,ex:"Swiss German dialects carry no social stigma; standard German is mostly kept for writing."},
      {q:"'Grüß Gott' literally comes from:",opts:["'May God greet you'","'Great God'","'Goodbye God'","'God is great'"],a:0,ex:"It is short for 'Grüß dich Gott' (may God greet/bless you), a traditional greeting of the Catholic south."}]},
    {t:"Dialect recap",s:"Review",qs:[
      {q:"Odd one out: which does NOT mean 'bread roll'?",opts:["Brezel","Semmel","Weck","Brötchen"],a:0,ex:"Semmel, Weck and Brötchen are regional words for a roll; a Brezel is a pretzel."},
      {q:"Which pairing of word and country is correct?",opts:["Jänner – Austria","parkieren – Austria","Grüezi – Germany","Moin – Switzerland"],a:0,ex:"'Jänner' is Austrian standard; 'parkieren' and 'Grüezi' are Swiss, 'Moin' is northern German."},
      {q:"'Sächsisch' is the dialect of the region around:",opts:["Dresden and Leipzig","Munich and Augsburg","Hamburg and Kiel","Zurich and Bern"],a:0,ex:"Saxon is spoken in Saxony, whose main cities are Dresden and Leipzig."}]},
    {t:"Varieties masterclass",s:"Challenge",qs:[
      {q:"Which statement about Austrian German is correct?",opts:["It is a standard with its own norms.","It is an incorrect form of German.","It is identical to Bavarian dialect.","It has no official dictionary."],a:0,ex:"German is pluricentric: Austria has its own standard and dictionary (Österreichisches Wörterbuch)."},
      {q:"Austrian 'Paradeiser' vs German 'Tomate' illustrates:",opts:["lexical variation between standards","a shift in dialect pronunciation","a change of grammatical gender","a recent spelling reform"],a:0,ex:"Both are standard words for tomato in their countries: the standards differ in vocabulary."},
      {q:"Swiss 'Velo', 'Trottoir' and 'Billett' show the influence of:",opts:["French","English","Italian","Latin"],a:0,ex:"Swiss Standard German borrows from French: Velo (bike), Trottoir (pavement), Billett (ticket)."}]}
  ],
  // Module 3: Rhetorical Control
  [
    {t:"Devices of persuasion",s:"Vocabulary",qs:[
      {q:"'die Anapher' is:",opts:["repetition of the opening word","a question needing no answer","a contrast of two opposites","an aside set off by dashes"],a:0,ex:"Anaphora repeats the same word at the start of successive clauses: 'Wir wollen …, wir wollen …'."},
      {q:"'eindringlich' describes a way of speaking that is:",opts:["urgent and insistent","quiet and shy","funny and light","vague and unclear"],a:0,ex:"An 'eindringliche' appeal presses hard on the listener; it is typical of persuasive speeches."},
      {q:"'an die Vernunft appellieren' means to:",opts:["appeal to reason","argue against reason","lose one's reason","explain a reason"],a:0,ex:"'appellieren an + accusative' means to appeal to someone's reason, conscience or sense."}]},
    {t:"Triad, escalation, aside",s:"Vocabulary",qs:[
      {q:"'der Dreiklang' in rhetoric is:",opts:["a set of three parallel items","a speech lasting three hours","a question repeated thrice","a song for three voices"],a:0,ex:"A triad ('Freiheit, Gleichheit, Brüderlichkeit') is memorable because of its balanced rhythm."},
      {q:"'die Zuspitzung' of an argument means:",opts:["sharpening it to a pointed claim","softening it into vagueness","translating it into English","postponing it until later"],a:0,ex:"'zuspitzen' = to sharpen to a point: the argument is pushed to a clear, provocative claim."},
      {q:"Which device inserts an aside without breaking the sentence?",opts:["die Parenthese","die Klimax","die Anapher","der Dreiklang"],a:0,ex:"A Parenthese is set off by dashes or commas: 'Das Ergebnis – und das ist entscheidend – überzeugt.'"}]},
    {t:"Speaking with emphasis",s:"Pronunciation",qs:[
      {q:"Listen. How should the intonation of these repeated questions develop?",say:"Ist das gerecht? Ist das klug? Ist das nötig?",opts:["increasing in intensity","falling into a whisper","staying perfectly flat","rising only on the first"],a:0,ex:"A series of rhetorical questions works as a climax: each should sound stronger than the last."},
      {q:"How is an aside like '– und das ist entscheidend –' usually spoken?",opts:["with a short pause on each side","faster, with no pauses at all","much louder than the rest","sung on a higher melody"],a:0,say:"Das Ergebnis – und das ist entscheidend – überzeugt.",ex:"Brief pauses (and often a lower pitch) frame the Parenthese so the main line stays audible."},
      {q:"Where is the stress in 'Anapher'?",opts:["a-NA-pher","A-na-pher","a-na-PHER","equal on all"],a:0,say:"die Anapher",ex:"'Anapher' is stressed on the second syllable [a-NA-fer], with 'ph' pronounced as f."}]},
    {t:"Building a climax",s:"Grammar",qs:[
      {q:"Which order forms a correct Klimax?",opts:["Es war gut, es war großartig, es war einzigartig.","Es war einzigartig, es war großartig, es war gut.","Es war großartig, es war gut, es war einzigartig.","Es war einzigartig, es war gut, es war großartig."],a:0,ex:"A Klimax rises from weak to strong: gut < großartig < einzigartig."},
      {q:"Complete the anaphora: 'Wir brauchen Mut, ___ Geduld, ___ Zusammenhalt.'",opts:["wir brauchen / wir brauchen","und auch / und dann","wir haben / es gibt","sowie / ebenso wie"],a:0,ex:"Anaphora repeats the same opening words in each clause, so 'wir brauchen' must recur."},
      {q:"Which sentence contains a Parenthese?",opts:["Der Plan – das wissen alle – ist riskant.","Der Plan ist riskant, das wissen alle.","Alle wissen, dass der Plan riskant ist.","Riskant ist der Plan, wie alle wissen."],a:0,ex:"A Parenthese interrupts the main clause in the middle, and the clause then continues."}]},
    {t:"Devices in context",s:"Grammar",qs:[
      {q:"Which is a rhetorical question?",opts:["Wollen wir wirklich tatenlos zusehen?","Wann beginnt die Sitzung morgen?","Wie viele Mitglieder hat der Verein?","Wo ist bitte der Konferenzraum?"],a:0,ex:"A rhetorical question seeks no information; its implied answer ('Nein!') steers the audience."},
      {q:"Choose the correct punctuation of the aside.",opts:["Die Reform, so viel ist klar, kommt zu spät.","Die Reform so viel ist klar, kommt zu spät.","Die Reform, so viel ist klar kommt zu spät.","Die Reform so viel, ist klar kommt zu spät."],a:0,ex:"An inserted Parenthese must be closed off on both sides, by two commas or two dashes."},
      {q:"'Nicht morgen, nicht übermorgen, sondern jetzt!' combines anaphora with:",opts:["a pointed climax (Zuspitzung)","a mixing of senses","an inserted Parenthese","a deliberate understatement"],a:0,ex:"The repeated 'nicht' builds tension that is released in the sharp final point 'jetzt'."}]},
    {t:"Reading: a speech excerpt",s:"Reading",qs:[
      {q:"Read: 'Wir haben gearbeitet, wir haben gekämpft, wir haben gewonnen.' Which devices dominate?",opts:["anaphora and triad","Parenthese and irony","understatement","synaesthesia"],a:0,ex:"'wir haben' opens all three clauses (anaphora), and the three steps form a triad."},
      {q:"Read: 'Man sagt, Bildung sei teuer. Wissen Sie, was teurer ist? Keine Bildung.' What does the speaker do?",opts:["answers their own question","asks the audience for data","admits education costs too much","changes the topic entirely"],a:0,ex:"The speaker raises a question and answers it at once, turning the cost argument around."},
      {q:"Read: 'Ich appelliere an Sie alle: Handeln Sie jetzt, bevor es zu spät ist.' The tone is:",opts:["eindringlich","gelassen","ironisch","gleichgültig"],a:0,ex:"A direct appeal, an imperative and a warning ('bevor es zu spät ist') make it urgent."}]},
    {t:"Listening: political rhetoric",s:"Listening",qs:[
      {q:"Listen. Which device do you hear?",say:"Wir kamen, wir sahen, wir siegten.",opts:["anaphora in a triad","a rhetorical question","a Parenthese","an oxymoron"],a:0,ex:"Caesar's 'veni, vidi, vici' in German: 'wir' opens three parallel clauses."},
      {q:"Listen. What is the speaker's conclusion?",say:"Ist das gerecht? Nein. Ist das vernünftig? Nein. Müssen wir es ändern? Ja.",opts:["Change is necessary.","Things are fair as they are.","The issue is unimportant.","Nothing can be done."],a:0,ex:"Two 'Nein' answers prepare the final 'Ja': the questions lead the audience to demand change."},
      {q:"Listen. How does the speaker judge the reform?",say:"Diese Reform – und ich sage das ganz bewusst – ist ein historischer Fehler.",opts:["as a historic mistake","as a historic success","as a minor detail","as too early to judge"],a:0,ex:"The aside 'und ich sage das ganz bewusst' adds weight to the harsh verdict 'historischer Fehler'."}]},
    {t:"Persuading an audience",s:"Speaking",qs:[
      {q:"You want to open a persuasive speech. Best start?",opts:["Stellen Sie sich vor, morgen gäbe es kein Wasser mehr.","Also, ich rede jetzt einfach mal über Wasser.","Wasser ist irgendwie auch ganz schön wichtig.","Ich weiß nicht genau, was ich sagen soll."],a:0,ex:"A vivid hypothetical in Konjunktiv II ('Stellen Sie sich vor …') draws the audience in at once."},
      {q:"Which closing line is the most eindringlich?",opts:["Handeln wir – jetzt, gemeinsam, entschlossen!","Vielleicht könnte man eventuell etwas tun.","Na ja, schauen wir mal, was so passiert.","Das war's dann so weit von meiner Seite."],a:0,ex:"An inclusive imperative plus a triad ('jetzt, gemeinsam, entschlossen') creates urgency."},
      {q:"An opponent says your plan is too expensive. Best rhetorical reply?",opts:["Zu teuer? Teuer wird es, wenn wir nichts tun.","Das stimmt nicht, Sie haben keine Ahnung.","Mag sein, aber das ist mir eigentlich egal.","Darüber möchte ich jetzt nicht sprechen."],a:0,ex:"Echoing the objection as a question and reversing it ('teuer wird es …') turns it into your argument."}]},
    {t:"Writing an op-ed",s:"Writing",qs:[
      {q:"Choose the correctly punctuated sentence.",opts:["Wer zahlt am Ende? Wir alle.","Wer zahlt am Ende, wir alle?","Wer zahlt am Ende. Wir alle?","Wer zahlt, am Ende wir alle."],a:0,ex:"The question gets a question mark, and the punchy answer stands as its own short statement."},
      {q:"Fill the gap: 'Wir appellieren ___ die Regierung, endlich zu handeln.'",opts:["an","auf","für","zu"],a:0,ex:"'appellieren' takes 'an + accusative': an die Regierung."},
      {q:"Which sentence keeps the parallel structure of a triad?",opts:["Wir wollen bauen, forschen und gestalten.","Wir wollen bauen, Forschung und gestalten.","Wir wollen bauen, forschen und die Gestaltung.","Wir wollen Bau, forschen und gestalten."],a:0,ex:"A triad needs three items of the same form; mixing verbs and nouns breaks the rhythm."}]},
    {t:"Famous German speeches",s:"Culture",qs:[
      {q:"'Ich bin ein Berliner' (1963) was said by:",opts:["John F. Kennedy","Willy Brandt","Konrad Adenauer","Ronald Reagan"],a:0,ex:"Kennedy said it in West Berlin in 1963 as a gesture of solidarity during the Cold War."},
      {q:"In 1985 Richard von Weizsäcker called 8 May 1945 a day of:",opts:["Befreiung (liberation)","Niederlage (defeat)","Feier (celebration)","Rache (revenge)"],a:0,ex:"His speech framed the end of the war as liberation from Nazi tyranny, a landmark in German memory."},
      {q:"In German political culture, highly emotional rhetoric often meets:",opts:["scepticism","enthusiasm","indifference","nostalgia"],a:0,ex:"Because of Nazi-era propaganda, many Germans distrust demagogic speech and prefer sober argument."}]},
    {t:"Rhetoric recap",s:"Review",qs:[
      {q:"Which word means 'urgent, insistent'?",opts:["eindringlich","eindeutig","einleuchtend","einsichtig"],a:0,ex:"eindeutig = unambiguous, einleuchtend = convincing, einsichtig = understanding or reasonable."},
      {q:"'die Zuspitzung' and 'die Klimax' both involve:",opts:["building toward a strong point","softening the message","repeating the first word","adding an aside"],a:0,ex:"Both devices increase intensity until the argument reaches its sharpest point."},
      {q:"'Wer, wenn nicht wir? Wann, wenn nicht jetzt?' combines rhetorical questions with:",opts:["parallelism","synaesthesia","understatement","a Parenthese"],a:0,ex:"The two questions mirror each other's structure, which makes the call to action memorable."}]},
    {t:"Rhetoric masterclass",s:"Challenge",qs:[
      {q:"Anaphora in a speech works best when the repeated phrase:",opts:["opens each new clause or paragraph","appears only once at the end","is placed in brackets","changes its form each time"],a:0,ex:"The effect depends on recognisable repetition at the start, as in 'I have a dream …'."},
      {q:"Which sentence is a Klimax and not just a list?",opts:["Er zweifelte, er verzweifelte, er zerbrach.","Er kaufte Brot, Käse und Milch.","Sie kam, sie aß, sie ging.","Rot, Gelb und Grün leuchteten."],a:0,ex:"Doubt, despair, breaking down: each step is more intense; the others are neutral sequences."},
      {q:"'Ich will gar nicht davon reden, dass das Projekt Millionen verschlungen hat.' This device is:",opts:["Praeteritio","Anapher","Klimax","Synästhesie"],a:0,ex:"Praeteritio draws attention to a point by pretending to pass over it."}]}
  ],
  // Module 4: Literary Texture
  [
    {t:"Talking about narrative",s:"Vocabulary",qs:[
      {q:"'der Erzähler' is:",opts:["the narrator","the editor","the villain","the publisher"],a:0,ex:"The narrator is the voice telling the story, which is not necessarily the author."},
      {q:"'die Erzählperspektive' refers to:",opts:["the narrative point of view","the length of the novel","the design of the cover","the order of chapters"],a:0,ex:"It describes from whose viewpoint and with how much knowledge a story is told."},
      {q:"'anschauliches' writing is:",opts:["vivid and easy to picture","dull and abstract","short and incomplete","full of errors"],a:0,ex:"'anschaulich' comes from 'anschauen' (look at): the reader can see what is described."}]},
    {t:"Devices and motifs",s:"Vocabulary",qs:[
      {q:"'das Leitmotiv' is:",opts:["a recurring motif in a work","the title of a work","the last line of a poem","the author's biography"],a:0,ex:"A Leitmotiv returns throughout a work, linking scenes and underlining a theme."},
      {q:"'der Bewusstseinsstrom' presents:",opts:["a character's unfiltered thoughts","a clear chronological report","a dialogue between narrators","a list of historical facts"],a:0,ex:"Stream of consciousness renders thoughts as they flow, often without logic or full sentences."},
      {q:"'Sein Wort war Gesetz.' is a:",opts:["Metapher","Vergleich","Personifikation","Lautmalerei"],a:0,ex:"It equates two things without 'wie'; with 'wie' it would be a simile (Vergleich)."}]},
    {t:"Sound and rhythm in poetry",s:"Pronunciation",qs:[
      {q:"Which word imitates the sound it describes (Lautmalerei)?",opts:["zischen","denken","Tisch","grün"],a:0,say:"zischen",ex:"'zischen' (to hiss) imitates its own sound, like 'summen' (hum) and 'knistern' (crackle)."},
      {q:"Listen. Which sound is repeated (alliteration)?",say:"Milch macht müde Männer munter.",opts:["m","l","ch","t"],a:0,ex:"Alliteration repeats the initial consonant of stressed words: Milch, macht, müde, Männer, munter."},
      {q:"How is the final 'v' in 'Leitmotiv' pronounced?",opts:["like f","like w","like English v","silent"],a:0,say:"das Leitmotiv",ex:"Word-final v in 'Motiv' is devoiced to [f]; only in the plural 'Motive' does it sound like [v]."}]},
    {t:"Präteritum in narration",s:"Grammar",qs:[
      {q:"Literary narration in German is typically written in the:",opts:["Präteritum","Perfekt","Futur I","Präsens only"],a:0,ex:"The Präteritum is the classic narrative tense of written fiction; the Perfekt dominates speech."},
      {q:"Complete: 'Die Zeit ___ dahin.'",opts:["kroch","kriechte","gekrochen","kriecht hat"],a:0,ex:"'kriechen' is a strong verb: kriechen – kroch – gekrochen; '*kriechte' does not exist."},
      {q:"Complete: 'Ein leises Blau ___ über dem Tal.'",opts:["lag","liegte","lagte","gelag"],a:0,ex:"'liegen' is strong (liegen – lag – gelegen) and describes position, so 'über dem Tal' takes dative."}]},
    {t:"Konjunktiv for literary effect",s:"Grammar",qs:[
      {q:"'Es war, als ob die Welt stillstünde.' Why Konjunktiv II?",opts:["to express an unreal comparison","to report someone's speech","to give a command","to mark future time"],a:0,ex:"'als ob' introduces an imagined comparison, so the verb is in Konjunktiv II (stillstünde)."},
      {q:"Complete: 'Er sah aus, als ___ er seit Tagen nicht geschlafen.'",opts:["hätte","habe gehabt","hat","würde"],a:0,ex:"'als' alone is followed directly by the subjunctive verb: 'als hätte er … geschlafen'."},
      {q:"Which sentence is correct?",opts:["Es schien, als ob er träumte.","Es schien, als ob träumte er.","Es schien, als er träumte ob.","Es schien, als träumt ob er."],a:0,ex:"'als ob' sends the verb to the end; only 'als' alone takes the verb directly after it."}]},
    {t:"Reading: a literary passage",s:"Reading",qs:[
      {q:"Read: 'Der Wind flüsterte in den Bäumen, und die Nacht hielt den Atem an.' Which device is used?",opts:["Personifikation","Synästhesie","Anapher","Klimax"],a:0,ex:"Wind and night are given human actions (whispering, holding breath): that is personification."},
      {q:"Read: 'Ich muss los, aber der Brief, wo ist der Brief, Mutter hat ihn sicher, nein, auf dem Tisch …' This style is:",opts:["Bewusstseinsstrom","auktoriales Erzählen","eine Ballade","ein Sachtext"],a:0,ex:"Jumping, unfinished thoughts rendered directly from inside a mind are stream of consciousness."},
      {q:"Read: 'Sie lächelte. Doch ihre Hände zitterten, als sie die Tasse abstellte.' What is the subtext?",opts:["She is nervous despite smiling.","She is calm and truly happy.","She is cold and very tired.","The cup has just broken."],a:0,ex:"The contrast between smile and shaking hands hints at a tension the narrator does not name."}]},
    {t:"Listening: images in words",s:"Listening",qs:[
      {q:"Listen. Which device appears?",say:"Ein warmer Klang erfüllte den Raum.",opts:["Synästhesie","Personifikation","Anapher","Parenthese"],a:0,ex:"'warm' (touch) describes 'Klang' (hearing): two senses are mixed."},
      {q:"Listen. What scene is described?",say:"Die Stadt schlief, nur die Laternen hielten Wache.",opts:["a quiet city at night","a busy market at noon","a storm at sea","a party at dawn"],a:0,ex:"Personification: the city 'sleeps' and the lamps 'keep watch', evoking a silent night."},
      {q:"Listen. Which device is used?",say:"Er rauchte eine nachdenkliche Zigarette.",opts:["Hypallage","Alliteration","Klimax","Anapher"],a:0,ex:"The smoker, not the cigarette, is thoughtful: the adjective is transferred to another noun."}]},
    {t:"Literary circle talk",s:"Speaking",qs:[
      {q:"In a discussion you want to cite textual evidence. Best phrase?",opts:["Das zeigt sich zum Beispiel in Zeile 12, wo …","Ich finde einfach, dass es halt so ist.","Das ist so, weil ich es eben so sehe.","Keine Ahnung, aber es klingt irgendwie gut."],a:0,ex:"Academic discussion backs claims with concrete passages; 'zeigt sich in Zeile …' does exactly that."},
      {q:"Someone says the narrator is simply the author. Best academic reply?",opts:["Man sollte Erzähler und Autor unterscheiden.","Genau, Erzähler und Autor sind immer dieselbe Person.","Das ist doch hier völlig egal, oder?","Autoren schreiben sowieso nie über sich."],a:0,ex:"Literary analysis separates the narrating voice from the real author, even in first-person texts."},
      {q:"Which comment describes a style precisely?",opts:["Die Sprache ist knapp, nüchtern, fast protokollarisch.","Die Sprache ist irgendwie schön und auch ganz nett.","Das Buch ist gut geschrieben und spannend zu lesen.","Der Stil gefällt mir halt, ich kann's nicht erklären."],a:0,ex:"Precise adjectives such as 'knapp, nüchtern' describe style – fitting, for example, Kafka's prose."}]},
    {t:"Writing creative prose",s:"Writing",qs:[
      {q:"Which sentence is the most anschaulich?",opts:["Regen trommelte auf das Blechdach.","Es regnete ziemlich stark draußen.","Das Wetter war an dem Tag schlecht.","Draußen war es irgendwie sehr nass."],a:0,ex:"A concrete verb ('trommelte') and object ('Blechdach') let the reader hear and see the rain."},
      {q:"What is an Enjambement?",opts:["A sentence runs on past the line break.","Each line ends with a full stop.","Two lines rhyme at the end.","A line repeats the previous one."],a:0,ex:"In enjambement the syntax carries over into the next line, creating tension or flow."},
      {q:"Fill the gap: 'Als sie das Haus betrat, ___ es still.'",opts:["war","ist","wäre gewesen","sei"],a:0,ex:"An 'als' clause about a single past event pairs with the narrative Präteritum: 'war'."}]},
    {t:"German literary classics",s:"Culture",qs:[
      {q:"Who wrote 'Die Verwandlung'?",opts:["Franz Kafka","Thomas Mann","Günter Grass","Hermann Hesse"],a:0,ex:"Kafka's 1915 novella opens with Gregor Samsa waking up transformed into a giant insect."},
      {q:"'Die Blechtrommel' (1959) is by:",opts:["Günter Grass","Heinrich Böll","Thomas Mann","Bertolt Brecht"],a:0,ex:"Grass's novel, narrated by Oskar Matzerath, is a key work of post-war German literature."},
      {q:"Thomas Mann's 'Buddenbrooks' tells the decline of:",opts:["a merchant family","a royal dynasty","a mountain village","a theatre troupe"],a:0,ex:"The 1901 novel follows four generations of a Lübeck merchant family; Mann won the Nobel Prize in 1929."}]},
    {t:"Literary recap",s:"Review",qs:[
      {q:"Odd one out: which is NOT a stylistic device?",opts:["Erzähler","Metapher","Synästhesie","Personifikation"],a:0,ex:"Metaphor, synaesthesia and personification are devices; the narrator is an element of narrative."},
      {q:"'Die Zeit kroch dahin.' combines the Präteritum with:",opts:["a metaphor of slowness","a Parenthese","a rhetorical question","an anaphora"],a:0,ex:"Time cannot crawl: the image of 'kriechen' makes the slowness felt."},
      {q:"Which phrase is a synaesthesia?",opts:["ein schreiendes Rot","ein rotes Kleid","ein lautes Auto","ein kalter Wind"],a:0,ex:"'schreiend' (hearing) describes a colour (sight); the others stay within one sense."}]},
    {t:"Literary masterclass",s:"Challenge",qs:[
      {q:"An 'auktorialer Erzähler' is:",opts:["all-knowing and comments on events","limited to one character's view","a character speaking as 'I'","absent, with only dialogue shown"],a:0,ex:"The authorial narrator knows everything, looks into all minds and may comment on the story."},
      {q:"'Er erzählte, er sei krank gewesen.' The Konjunktiv I signals:",opts:["reported, unconfirmed speech","an unreal, impossible wish","a polite request","a plan for the future"],a:0,ex:"Konjunktiv I marks indirect speech: the narrator reports his claim without vouching for it."},
      {q:"Why might an author repeat images of 'Kälte' throughout a novel?",opts:["to link scenes and deepen a theme","to fill pages with repetition","to mark the end of chapters","to correct earlier mistakes"],a:0,ex:"A recurring image works as a Leitmotiv, e.g. coldness for emotional isolation."}]}
  ],
  // Module 5: Specialized & Masterclass Tasks
  [
    {t:"Field-specific words",s:"Vocabulary",qs:[
      {q:"'die Fachsprache' is:",opts:["the technical language","a foreign language","the everyday slang","a regional dialect"],a:0,ex:"Fachsprache is the precise terminology of a field such as law, medicine or economics."},
      {q:"'das Fachgebiet' means:",opts:["field of expertise","specialist shop","subject index","free time"],a:0,ex:"'Fach' = subject or specialism, 'Gebiet' = area: one's professional or academic field."},
      {q:"'die Hypothese' in academic language is:",opts:["an assumption to be tested","a proven law of nature","the final summary","a list of sources"],a:0,ex:"A hypothesis is a provisional claim that research tries to confirm or refute."}]},
    {t:"Translation vocabulary",s:"Vocabulary",qs:[
      {q:"'dolmetschen' means to:",opts:["interpret orally","translate in writing","edit a text","read aloud"],a:0,ex:"Dolmetschen is live spoken translation; Übersetzen usually refers to written texts."},
      {q:"A 'sinngemäße' translation is:",opts:["by meaning, not literally","word for word, exactly","shortened by half","in rhyming verse"],a:0,ex:"'sinngemäß' = according to the sense: it keeps the meaning, not the exact wording."},
      {q:"'die Entsprechung' of a term is its:",opts:["equivalent","origin","spelling","opposite"],a:0,ex:"From 'entsprechen' (correspond to): the matching term in another language or system."}]},
    {t:"Long technical words",s:"Pronunciation",qs:[
      {q:"Listen. Where is the main stress in this compound?",say:"das Bruttoinlandsprodukt",opts:["on 'Brut-'","on '-in-'","on '-pro-'","on '-dukt'"],a:0,ex:"German compounds are normally stressed on their first element: BRUTTO-inlands-produkt."},
      {q:"How is 'ts' in 'Rechtsbeistand' pronounced?",opts:["like z in 'Zeit'","like s in 'sie'","like 'sch'","it is silent"],a:0,say:"der Rechtsbeistand",ex:"'ts', 'tz' and 'z' all stand for the sound [ts] in German: rechts, Satz, Zeit."},
      {q:"In 'Hypothese', the 'y' sounds like:",opts:["ü","i","j","u"],a:0,say:"die Hypothese",ex:"In Greek loanwords 'y' is pronounced like ü: Hypothese, Physik, System."}]},
    {t:"Nominal style in Fachsprache",s:"Grammar",qs:[
      {q:"Which is the nominal form of 'Das BIP wächst um zwei Prozent.'?",opts:["das Wachstum des BIP um zwei Prozent","das wachsende BIP von zwei Prozent","das BIP, wachsend um zwei Prozent","der Wuchs des BIP zu zwei Prozent"],a:0,ex:"The verb 'wachsen' becomes 'das Wachstum', the subject becomes a genitive, and 'um' stays."},
      {q:"Complete: 'Der Sachverhalt ist ___ komplex.' (legally)",opts:["juristisch","juristische","juristischen","Juristik"],a:0,ex:"As an adverb modifying 'komplex', 'juristisch' stays uninflected."},
      {q:"Choose the correct genitive for a legal text.",opts:["die Rechte des Angeklagten","die Rechte des Angeklagte","die Rechte dem Angeklagten","die Rechte von dem Angeklagter"],a:0,ex:"Nominalised adjectives decline: des Angeklagten; legal style prefers the genitive to 'von'."}]},
    {t:"Passive and impersonal style",s:"Grammar",qs:[
      {q:"'Schadenfreude lässt sich kaum übersetzen.' means:",opts:["Schadenfreude can hardly be translated.","Schadenfreude can hardly be learned.","Schadenfreude lets itself go.","Nobody wants to translate it."],a:0,ex:"'sich lassen + infinitive' is a passive alternative expressing possibility (= kann übersetzt werden)."},
      {q:"Which sentence is a correct passive?",opts:["Der Vertrag wurde gestern unterzeichnet.","Der Vertrag hat gestern unterzeichnet.","Der Vertrag wurde gestern unterzeichnen.","Der Vertrag ist gestern unterzeichnen."],a:0,ex:"The Vorgangspassiv is 'werden' + past participle: wurde … unterzeichnet."},
      {q:"Rephrase with '-bar': 'Der Begriff kann nicht übersetzt werden.'",opts:["Der Begriff ist unübersetzbar.","Der Begriff ist übersetzbarlos.","Der Begriff ist nichtübersetzbar.","Der Begriff ist übersetzunbar."],a:0,ex:"'un- + verb stem + -bar' expresses impossibility in a single adjective: unübersetzbar."}]},
    {t:"Reading: expert texts",s:"Reading",qs:[
      {q:"Read: 'Das Bruttoinlandsprodukt stieg im dritten Quartal um 0,3 Prozent, nachdem es zuvor stagniert hatte.' What happened before?",opts:["The economy had not grown.","The economy had shrunk sharply.","The economy had grown fast.","The data was missing."],a:0,ex:"'stagnieren' means to stand still: before the 0.3% rise there was no growth."},
      {q:"Read: 'Der Mandant wurde von seinem Rechtsbeistand über seine Rechte aufgeklärt.' Who informed the client?",opts:["his lawyer","the judge","the police","his family"],a:0,ex:"'Rechtsbeistand' is legal counsel; in the passive, 'von' introduces the agent."},
      {q:"Read: 'Die Hypothese konnte durch die Daten nicht bestätigt werden.' What is true?",opts:["The data did not support it.","The data proved it right.","No data was collected.","It was confirmed twice."],a:0,ex:"'nicht bestätigt werden konnte' = could not be confirmed: the data failed to support the hypothesis."}]},
    {t:"Listening: expert talk",s:"Listening",qs:[
      {q:"Listen. What does the speaker explain?",say:"Fernweh ist die Sehnsucht nach fernen Orten.",opts:["a longing for faraway places","a fear of long journeys","a longing for home","a type of package holiday"],a:0,ex:"'Sehnsucht nach fernen Orten' defines Fernweh; a longing for home would be Heimweh."},
      {q:"Listen. What is the speaker's job?",say:"Ich bin Dolmetscherin, ich übertrage also mündlich.",opts:["interpreting speech","translating novels","teaching grammar","editing newspapers"],a:0,ex:"A Dolmetscherin works orally ('mündlich'), translating spoken language live."},
      {q:"Listen. How well does the study support the hypothesis?",say:"Die Studie stützt unsere Hypothese nur teilweise.",opts:["only partly","fully","not at all","strongly"],a:0,ex:"'nur teilweise' = only partially: some results fit, others do not."}]},
    {t:"Masterclass Q&A",s:"Speaking",qs:[
      {q:"After your expert talk, you don't know an answer. Best response?",opts:["Eine gute Frage – das müsste ich nachprüfen.","Das weiß doch jeder, nächste Frage bitte.","Keine Ahnung, ist mir auch ziemlich egal.","Darauf antworte ich grundsätzlich nicht."],a:0,ex:"Acknowledging the question and promising to check keeps credibility and the expert register."},
      {q:"You must explain 'Feierabend' to an English audience. Best approach?",opts:["Describe it: free time after work.","Translate it as 'party evening'.","Say it means nothing in English.","Spell it slowly and move on."],a:0,ex:"Untranslatables are best rendered by explanation; 'party evening' is a false literal rendering."},
      {q:"A client asks for 'eine sinngemäße Übersetzung'. What do they want?",opts:["meaning over literal wording","every word kept exactly","a summary in bullet points","a spoken interpretation"],a:0,ex:"'sinngemäß' prioritises the sense and natural target-language wording over literal fidelity."}]},
    {t:"Writing a translator's note",s:"Writing",qs:[
      {q:"Choose the best translator's note for 'Schadenfreude'.",opts:["Lehnwort; Bedeutung: Freude am Unglück anderer.","Wörtlich übersetzt als 'damage joy' im Text.","Durch 'happiness' ersetzt, da es kürzer ist.","Ausgelassen, da es nicht übersetzbar ist."],a:0,ex:"Keeping the loanword and glossing its meaning preserves nuance; the other options distort or delete it."},
      {q:"Which sentence is correctly written?",opts:["Die Dolmetscherin arbeitet simultan.","Die Dolmätscherin arbeitet simultan.","Die Dolmetscherin arbeitet simmultan.","Die Dolmetscherin arbeited simultan."],a:0,ex:"Spelling: Dolmetscherin with e, 'simultan' with one m, and 'arbeitet' with a final t."},
      {q:"Fill the gap: 'Für diesen Begriff gibt es im Englischen keine genaue ___.'",opts:["Entsprechung","Entsprechen","Entspricht","Sprechung"],a:0,ex:"After 'keine genaue' a feminine noun is needed: 'die Entsprechung' (the equivalent)."}]},
    {t:"Untranslatable German",s:"Culture",qs:[
      {q:"'Feierabend' refers to:",opts:["the end of the working day","a national public holiday","a birthday party at work","the evening of New Year"],a:0,ex:"'Feierabend' is the time after work, and 'Schönen Feierabend!' wishes someone a nice evening off."},
      {q:"'Fernweh' is the opposite of:",opts:["Heimweh","Weltschmerz","Wanderlust","Zeitgeist"],a:0,ex:"Fernweh is longing for distant places; Heimweh is longing for home."},
      {q:"Which German word is an established English loanword?",opts:["Zeitgeist","Sachverhalt","Feierabend","Rechtsbeistand"],a:0,ex:"'Zeitgeist' (spirit of the age) is standard in English; the others are not used in English."}]},
    {t:"Specialist recap",s:"Review",qs:[
      {q:"Odd one out by domain:",opts:["die Hypothese","der Rechtsbeistand","der Sachverhalt","das Urteil"],a:0,ex:"Rechtsbeistand, Sachverhalt and Urteil belong to law; Hypothese belongs to academic research."},
      {q:"Which statement about Übersetzen and Dolmetschen is true?",opts:["Übersetzen is written, Dolmetschen spoken.","Both mean only spoken translation.","Dolmetschen is written, Übersetzen spoken.","Both mean only written translation."],a:0,ex:"Translators work with written text, interpreters render speech live, simultaneously or consecutively."},
      {q:"'BIP' stands for:",opts:["Bruttoinlandsprodukt","Bundesinlandsprodukt","Bruttoindustrieprodukt","Bundesindexpreis"],a:0,ex:"BIP = gross domestic product (GDP), the value of all goods and services produced in a country."}]},
    {t:"Masterclass editing",s:"Challenge",qs:[
      {q:"At this level, an editor must preserve:",opts:["register, intent and nuance together","only the correct spelling","only the length of the text","only the technical terms"],a:0,ex:"Expert editing changes form without losing tone, purpose or subtle meaning."},
      {q:"Which version keeps the formal register of 'Wir bitten um Ihr Verständnis.'?",opts:["Wir ersuchen um Ihr Verständnis.","Sorry, ist halt so, Leute.","Bitte habt Verständnis, Leute.","Checkt das mal bitte, okay?"],a:0,ex:"'ersuchen um' is an elevated, official synonym of 'bitten um'; the others drop into slang."},
      {q:"'Der Angeklagte bestreitet den Sachverhalt.' Best English rendering:",opts:["The defendant disputes the facts.","The accused is fighting the matter.","The defendant contests the judge.","The accused denies the law."],a:0,ex:"'bestreiten' = to dispute or deny; 'Sachverhalt' = the facts of the case in legal language."}]}
  ],
  // Module 6: Exam Practice & Final Project
  [
    {t:"Exam key words",s:"Vocabulary",qs:[
      {q:"'angeblich' means:",opts:["allegedly","certainly","recently","fortunately"],a:0,ex:"'angeblich' marks a claim made by others that the speaker does not confirm."},
      {q:"'abschließend' in a presentation signals:",opts:["the conclusion","the introduction","a digression","a question"],a:0,ex:"From 'abschließen' (to conclude): 'Abschließend …' introduces the final part."},
      {q:"'das Abschlussprojekt' is:",opts:["the final project","the first draft","the exam fee","the class trip"],a:0,ex:"'Abschluss' = completion or end: the project that concludes the course."}]},
    {t:"Reformulation vocabulary",s:"Vocabulary",qs:[
      {q:"'einen Begriff umschreiben' means to:",opts:["paraphrase a term","delete a term","translate a term","spell a term"],a:0,ex:"Inseparable 'umschreiben' (er umschreibt) = to express in other words; separable 'umschreiben' = rewrite."},
      {q:"'Es sei darauf hingewiesen, dass …' means:",opts:["It should be noted that …","It was pointed out that …","Point at the fact that …","It is denied that …"],a:0,ex:"The Konjunktiv I 'sei' makes a formal impersonal request, typical of academic writing."},
      {q:"'die Umformulierung' is:",opts:["the reformulation","the uniform design","the formula sheet","the political reform"],a:0,ex:"'um-' (re-) + 'Formulierung' (wording): saying the same thing in a different form."}]},
    {t:"Stress for exam speaking",s:"Pronunciation",qs:[
      {q:"In 'Er umschreibt den Begriff.', where is the stress in the verb?",opts:["on '-schreibt'","on 'um-'","equally on both","on neither part"],a:0,say:"Er umschreibt den Begriff.",ex:"Inseparable verbs stress the stem (umSCHREIBT); separable UMschreiben (rewrite) stresses the prefix."},
      {q:"Listen. Which syllable of 'angeblich' is stressed?",say:"angeblich",opts:["an-","-geb-","-lich","none"],a:0,ex:"Like 'angeben', 'angeblich' carries the stress on its prefix: ANgeblich."},
      {q:"The 'ß' in 'abschließend' sounds like:",opts:["a voiceless s","a voiced z","sch","ts"],a:0,say:"abschließend",ex:"ß always stands for a voiceless [s], here after the diphthong 'ie' in 'schließen'."}]},
    {t:"Claims: soll, will, Konjunktiv I",s:"Grammar",qs:[
      {q:"'Der Minister soll von den Plänen gewusst haben.' means:",opts:["The minister is said to have known about the plans.","The minister should have known about the plans.","The minister wants to know about the plans.","The minister must have known about the plans."],a:0,ex:"'sollen' + perfect infinitive reports what others claim: 'is said to have'."},
      {q:"'Er will nichts gesehen haben.' expresses:",opts:["his own doubtful claim","a firm intention","an obligation","a report by others"],a:0,ex:"'wollen' + perfect infinitive means the subject himself claims it, and the speaker doubts it."},
      {q:"Report in Konjunktiv I: Sie sagte: 'Ich bin krank.'",opts:["Sie sagte, sie sei krank.","Sie sagte, sie ist krank gewesen.","Sie sagte, sie wäre gewesen krank.","Sie sagte, sie sein krank."],a:0,ex:"Konjunktiv I of 'sein' is 'sei'; the tense stays present and the pronoun shifts to 'sie'."}]},
    {t:"Same meaning, new form",s:"Grammar",qs:[
      {q:"Nominal form of 'Obwohl man sich intensiv bemühte, …':",opts:["Trotz intensiver Bemühungen …","Wegen intensiver Bemühungen …","Durch intensive Bemühungen …","Statt intensiver Bemühungen …"],a:0,ex:"Concessive 'obwohl' becomes 'trotz + genitive'; 'wegen' and 'durch' would change the meaning."},
      {q:"Passive of 'Die Kommission prüft den Antrag.':",opts:["Der Antrag wird von der Kommission geprüft.","Der Antrag wurde von der Kommission geprüft.","Der Antrag ist die Kommission geprüft.","Die Kommission wird den Antrag prüfen."],a:0,ex:"Present active becomes present passive 'wird … geprüft'; 'wurde' would change the tense."},
      {q:"Verbal form of 'Nach Abschluss der Verhandlungen …':",opts:["Nachdem die Verhandlungen abgeschlossen waren, …","Bevor die Verhandlungen abgeschlossen waren, …","Während die Verhandlungen abgeschlossen wurden, …","Weil die Verhandlungen abgeschlossen waren, …"],a:0,ex:"Temporal 'nach + noun' becomes a 'nachdem' clause with the earlier action in the past perfect."}]},
    {t:"Reading: fact or claim?",s:"Reading",qs:[
      {q:"Read: 'Der Konzern hat angeblich Millionen an Steuern hinterzogen.' What does the text say?",opts:["It reports an unproven accusation.","It states a proven fact.","It denies the accusation.","It predicts a future crime."],a:0,ex:"'angeblich' distances the writer: the tax evasion is alleged, not established."},
      {q:"Read: 'Laut Polizei sei der Täter geflohen.' Why the Konjunktiv I 'sei'?",opts:["It marks reported information.","It expresses a wish.","It is a spelling variant.","It marks a future event."],a:0,ex:"Konjunktiv I signals indirect speech: the writer reports the police statement without vouching for it."},
      {q:"Read: 'Die Zahl der Teilnehmer dürfte bei etwa 500 liegen.' The figure is:",opts:["an estimate","an exact count","an official claim","a denial"],a:0,ex:"'dürfte' + infinitive expresses a cautious assumption, so 500 is a speculation, not a fact."}]},
    {t:"Listening: exam-style news",s:"Listening",qs:[
      {q:"Listen. How certain is the information?",say:"Der Sänger soll bereits geheiratet haben.",opts:["It is a rumour.","It is confirmed.","It is denied.","It is planned."],a:0,ex:"'soll … geheiratet haben' passes on hearsay: the speaker does not confirm the wedding."},
      {q:"Listen. What does the speaker signal?",say:"Offenbar hat die Regierung ihre Pläne geändert.",opts:["an apparent change","a denied change","a future change","no change at all"],a:0,ex:"'offenbar' = apparently: the speaker infers the change from evidence but does not confirm it."},
      {q:"Listen. Which part of a presentation is this?",say:"Lassen Sie mich abschließend die wichtigsten Ergebnisse zusammenfassen.",opts:["the conclusion","the introduction","the Q&A","the main part"],a:0,ex:"'abschließend' and 'zusammenfassen' are classic signals of the closing section (Schluss)."}]},
    {t:"Defending your project",s:"Speaking",qs:[
      {q:"An examiner challenges your data. Best response?",opts:["Ein berechtigter Einwand – lassen Sie mich das präzisieren.","Das stimmt nicht, Sie haben das falsch verstanden.","Darüber habe ich ehrlich gesagt keine Lust zu reden.","Das steht doch alles schon in meinen Folien."],a:0,ex:"Acknowledging the objection and then clarifying shows confidence and keeps the formal register."},
      {q:"Best transition from the introduction to the main part?",opts:["Damit komme ich zum ersten Hauptpunkt.","Also, ähm, ja, dann geht's halt weiter.","Das war's, tschüss erst mal von mir.","Jetzt kommt irgendwie was anderes."],a:0,ex:"Signposting ('Damit komme ich zu …') makes the structure audible, which examiners assess."},
      {q:"Best opening line for your final project presentation?",opts:["In meinem Vortrag gehe ich der Frage nach, …","Hi Leute, also mein Thema ist so ungefähr …","Ich habe keine Ahnung, wo ich anfangen soll …","Abschließend möchte ich noch kurz sagen, …"],a:0,ex:"Naming the guiding question in formal register is a clear Einleitung; 'abschließend' belongs at the end."}]},
    {t:"Register in writing",s:"Writing",qs:[
      {q:"Which line opens a formal complaint?",opts:["Hiermit möchte ich mich über … beschweren.","Ey, euer Service ist echt total mies.","Ich wollte mal kurz ein bisschen meckern.","Hallo, das nervt mich gerade total."],a:0,ex:"'Hiermit möchte ich mich über … beschweren' is the standard formal opener; the others are colloquial."},
      {q:"Choose the correct sentence in reported speech.",opts:["Er behauptet, er habe nichts gewusst.","Er behauptet, er hat nichts wissen.","Er behauptet, er habe nichts gewisst.","Er behauptet, er hätte nichts gewissen."],a:0,ex:"Konjunktiv I 'habe' plus the correct participle 'gewusst' (wissen – wusste – gewusst)."},
      {q:"Fill the gap: '___ sei darauf hingewiesen, dass die Studie begrenzt ist.'",opts:["Es","Er","Das","Man"],a:0,ex:"The fixed formula uses the dummy subject 'es' in an impersonal passive: 'Es sei darauf hingewiesen'."}]},
    {t:"Exams and academic norms",s:"Culture",qs:[
      {q:"The Goethe-Zertifikat C2 is also called:",opts:["Großes Deutsches Sprachdiplom","Kleines Deutsches Sprachdiplom","Zertifikat Deutsch Plus","Deutsches Sprachabitur"],a:0,ex:"Its full name is 'Goethe-Zertifikat C2: Großes Deutsches Sprachdiplom' (GDS)."},
      {q:"In German academic presentations, the audience typically expects:",opts:["a clearly announced structure","a joke on every single slide","no fixed time limit at all","no questions afterwards"],a:0,ex:"An outline (Gliederung) at the start and strict timing are standard expectations."},
      {q:"In an oral exam, you address the examiner with:",opts:["Sie","du","ihr","man"],a:0,ex:"Exams are formal situations: the polite 'Sie' is expected unless the examiner offers 'du'."}]},
    {t:"Exam recap",s:"Review",qs:[
      {q:"Which word marks a claim rather than a fact?",opts:["angeblich","tatsächlich","nachweislich","bekanntlich"],a:0,ex:"'angeblich' distances the speaker; tatsächlich, nachweislich and bekanntlich present facts."},
      {q:"'Trotz aller Bemühungen' is the nominal form of:",opts:["Obwohl man sich sehr bemühte","Weil man sich sehr bemühte","Damit man sich sehr bemühte","Wenn man sich sehr bemühte"],a:0,ex:"'trotz' expresses concession, matching 'obwohl'; 'weil' would mean cause."},
      {q:"Which phrase introduces the conclusion?",opts:["Abschließend lässt sich festhalten, …","Zunächst möchte ich erläutern, …","Ein weiterer Aspekt ist dabei, …","Im Folgenden zeige ich Ihnen, …"],a:0,ex:"'Abschließend lässt sich festhalten' summarises at the end; the others open or continue a section."}]},
    {t:"Final exam challenge",s:"Challenge",qs:[
      {q:"Which sentence keeps the meaning of 'Man vermutet, dass der Täter geflohen ist.'?",opts:["Der Täter dürfte geflohen sein.","Der Täter ist sicher geflohen.","Der Täter will geflohen sein.","Der Täter muss jetzt fliehen."],a:0,ex:"'dürfte' + perfect infinitive keeps the cautious assumption; 'sicher' would make it a fact."},
      {q:"Indirect speech of 'Wir haben keine Zeit.' (they said):",opts:["Sie sagten, sie hätten keine Zeit.","Sie sagten, sie haben keine Zeit gehabt.","Sie sagten, wir hätten keine Zeit.","Sie sagten, sie habe keine Zeit."],a:0,ex:"Konjunktiv I 'haben' looks like the indicative, so Konjunktiv II 'hätten' replaces it; 'wir' becomes 'sie'."},
      {q:"Which reformulation changes the meaning?",opts:["Er soll das Geld genommen haben. → Er hat das Geld genommen.","Der Bericht wurde gestern veröffentlicht. → Man veröffentlichte den Bericht gestern.","Nach dem Essen ging er. → Nachdem er gegessen hatte, ging er.","Wegen des Regens blieb er. → Weil es regnete, blieb er."],a:0,ex:"'soll … genommen haben' only reports a claim; the indicative turns hearsay into a stated fact."}]}
  ]
];
